import type { Metadata } from "next";
import SitemapShell, {
  sitemapLinkClass,
  sitemapSectionHeadingClass,
} from "@/components/sitemap-directory/shell";
import {
  buildDestinationTree,
  getSitemapDirectoryCategories,
  type DestinationNode,
} from "@/services/sitemap/directory";

export const revalidate = 86400;

export const metadata: Metadata = {
  title: "Destinations Sitemap - TravelShop Booking",
  description:
    "All tour destinations on TravelShop Booking, organized by continent, country and city.",
  alternates: {
    canonical: "https://travelshopbooking.com/sitemap/destinations",
  },
};

/** Şehir altı (nadir) seviyeleri de tek düz listeye indirger. */
function flattenLeaves(nodes: DestinationNode[]): DestinationNode[] {
  return nodes.flatMap((node) => [node, ...flattenLeaves(node.children)]);
}

export default async function SitemapDestinationsPage() {
  const categories = await getSitemapDirectoryCategories();
  const roots = buildDestinationTree(categories);

  // Tipik durum: tek kök = worldwide sayfası; kıtaları üste çıkar, kökü lead-link yap
  const singleRoot =
    roots.length === 1 && roots[0].children.length > 0 ? roots[0] : null;
  const continents = singleRoot ? singleRoot.children : roots;

  return (
    <SitemapShell
      title="Destinations"
      intro="Every destination we operate in, organized by continent, country and city."
      crumbs={[
        { pageTitle: "Sitemap", pageUrl: "/sitemap" },
        { pageTitle: "Destinations", pageUrl: "/sitemap/destinations" },
      ]}
    >
      {singleRoot && (
        <p className="tw-mt-0 tw-mb-8 tw-text-[15px]">
          <a
            href={`/${singleRoot.pageUrl}`}
            className="tw-font-semibold tw-text-[#854ec9] tw-no-underline hover:tw-underline"
          >
            {singleRoot.title}
          </a>
        </p>
      )}

      <div className="tw-flex tw-flex-col tw-gap-12">
        {continents.map((continent) => (
          <section key={continent.id}>
            <h2 className={sitemapSectionHeadingClass}>
              <a
                href={`/${continent.pageUrl}`}
                className="tw-text-inherit tw-no-underline hover:tw-text-[#854ec9] tw-transition-colors"
              >
                {continent.title}
              </a>
            </h2>

            {/* Masonry kolonlar: grid'in satır hizalamasından doğan boşlukları önler */}
            <div className="tw-mt-5 tw-columns-1 md:tw-columns-2 xl:tw-columns-3 tw-gap-x-10">
              {continent.children.map((country) => (
                <div
                  key={country.id}
                  className="tw-break-inside-avoid tw-mb-7"
                >
                  <h3 className="tw-m-0 tw-text-[16px] tw-font-bold tw-text-[#14101c]">
                    <a
                      href={`/${country.pageUrl}`}
                      className="tw-text-inherit tw-no-underline hover:tw-text-[#854ec9] tw-transition-colors"
                    >
                      {country.shortTitle}
                    </a>
                  </h3>
                  {country.children.length > 0 && (
                    <ul className="tw-list-none tw-m-0 tw-mt-2 tw-p-0 [&>li]:tw-mb-1">
                      {flattenLeaves(country.children).map((city) => (
                        <li key={city.id}>
                          <a
                            href={`/${city.pageUrl}`}
                            className={sitemapLinkClass}
                          >
                            {city.shortTitle}
                          </a>
                        </li>
                      ))}
                    </ul>
                  )}
                </div>
              ))}
            </div>
          </section>
        ))}
      </div>
    </SitemapShell>
  );
}
